import sys
import re
import math
from collections import defaultdict

def parse_args():
    args = sys.argv[1:]
    if not args:
        print("Usage: python quote.py TEMPLATE_PATH OUTPUT_PATH NAME=VALUE [NAME=VALUE ...]", file=sys.stderr)
        sys.exit(1)
    template_path = args[0]
    output_path = args[1]
    name_value_pairs = {}
    for arg in args[2:]:
        if '=' not in arg:
            print(f"Invalid argument format: {arg}", file=sys.stderr)
            sys.exit(1)
        name, value_str = arg.split('=', 1)
        try:
            value = float(value_str)
        except ValueError:
            print(f"Invalid value for {name}: {value_str}", file=sys.stderr)
            sys.exit(1)
        name_value_pairs[name] = value
    return template_path, output_path, name_value_pairs

def evaluate_expression(expr, variables):
    try:
        return eval(expr, {'__builtins__': None}, variables)
    except NameError as e:
        print(f"Undefined variable: {e.args[0]}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error evaluating expression: {e}", file=sys.stderr)
        sys.exit(1)

def process_template(template_path, output_path, variables):
    with open(template_path, 'r', encoding='utf-8') as f:
        template = f.read()

    def replace_match(match):
        expr = match.group(1).strip()
        try:
            value = evaluate_expression(expr, variables)
            return f"{value:.2f}"
        except Exception:
            return match.group(0)

    processed = re.sub(r'\{\{([^}]*)\}\}', replace_match, template)
    with open(output_path, 'w', encoding='utf-8') as f:
        f.write(processed)

def main():
    template_path, output_path, variables = parse_args()
    process_template(template_path, output_path, variables)

if __name__ == "__main__":
    main()
